`,"todday-modas/public/assets/img/pwa/icon-180.png":"[PNG Binary Asset]","todday-modas/public/assets/img/pwa/icon-192.png":"[PNG Binary Asset]","todday-modas/public/assets/img/pwa/icon-32.png":"[PNG Binary Asset]","todday-modas/public/assets/img/pwa/icon-512.png":"[PNG Binary Asset]","todday-modas/public/assets/js/tm-public.js":`/* global tmPublicData, jQuery */
jQuery(document).ready(function($) {
    'use strict';

    // Banner de consentimento LGPD
    var consentKey = 'tm_cookie_consent';
    if (!localStorage.getItem(consentKey)) {
        $('#tm-consent-banner').fadeIn();
    }

    function recordConsent(categories) {
        localStorage.setItem(consentKey, categories);
        $('#tm-consent-banner').fadeOut();

        if (typeof tmPublicData !== 'undefined') {
            $.post(tmPublicData.ajaxUrl, {
                action: 'tm_record_consent',
                nonce: tmPublicData.consentNonce,
                categories: categories
            });
        }
    }

    $('#tm-accept-all').on('click', function() {
        recordConsent('essential,analytics,marketing');
    });

    $('#tm-accept-essential').on('click', function() {
        recordConsent('essential');
    });
});
`,"todday-modas/public/pwa/tm-sw.js":`// Service Worker PWA Todday Modas
var CACHE_NAME = 'tm-pwa-v1.0.27';
var ASSETS = [
    '/',
    '/wp-content/plugins/todday-modas/public/assets/css/tm-public.css',
    '/wp-content/plugins/todday-modas/public/assets/css/tm-variables.css',
    '/wp-content/plugins/todday-modas/public/assets/js/tm-public.js'
];

self.addEventListener('install', function(event) {
    event.waitUntil(
        caches.open(CACHE_NAME).then(function(cache) {
            return cache.addAll(ASSETS);
        })
    );
});

self.addEventListener('fetch', function(event) {
    event.respondWith(
        caches.match(event.request).then(function(response) {
            return response || fetch(event.request);
        })
    );
});
